@functools.lru_cache(maxsize=None)
def fibonacci(n):
    """Calculate the nth Fibonacci number efficiently using recursion with memoization."""
    if n <= 0:
        raise ValueError("Fibonacci sequence only defined for non-negative integers.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def fib_sum(a, b):
    """
    This function calculates the sum of Fibonacci numbers from 0 to 'a' minus the sum of Fibonacci numbers from 0 to 'b'.

    Args:
    - a: An integer representing the upper limit of the range in the first sum of Fibonacci numbers.
    - b: An integer representing the lower limit of the range in the second sum of Fibonacci numbers.

    Returns:
    - int: The calculated sum based on the given formula, or -1 if either 'a' or 'b' is less than 1.

    Edge Cases:
    - Both 'a' and 'b' must be greater than or equal to 1.
    - Neither 'a' nor 'b' can exceed 50 for efficient computation.
    """

    # Check if either 'a' or 'b' is less than 1
    if a < 1 or b < 1:
        return -1

    # Reset memoization state for the current call
    @functools.lru_cache(None)
    def _fib_helper(n):
        if n <= 0:
            raise ValueError("Fibonacci sequence only defined for non-negative integers.")
        elif n == 1:
            return 0
        elif n == 2:
            return 1
        else:
            return _fib_helper(n - 1) + _fib_helper(n - 2)

    # Calculate the required sums using dynamic programming approach with memoization
    fib_a = _fib_helper(a)
    fib_b = _fib_helper(b)

    # Handle the case when 'a' and 'b' are out of bounds
    if a > 50 or b > 50:
        return -1

    # Return the difference between the two sums
    return fib_a - fib_b

# Test the function
if __name__ == "__main__":
    print(fib_sum(3, 2))  # Expected output: 3
    print(fib_sum(5, 2))  # Expected output: 8
    print(fib_sum(1, 1))  # Expected output: 1
    print(fib_sum(6, 1))  # Expected output: -1

