def compute_F_m_n(m, n):
    """
    Computes F_m(n) % (m^2 - 1)
    """
    # Initialize a list to store intermediate results
    memo = [None] * (m)

    def helper(k):
        # Base case: F_1(n) = n
        if k == 1:
            return n

        # Check if the result is already computed
        if memo[k]:
            return memo[k]

        # Recursive call to get F_k(n)
        res = 2 * helper(k - 1) + 3
        # Update the memoization table
        memo[k] = res % (m ** 2 - 1)

        return memo[k]

    # Compute F_m(n)
    return helper(m)

