import sys

def gcd(a, b):
    """Compute the greatest common divisor of two numbers."""
    while b != 0:
        t = b
        b = a % b
        a = t
    return a

def mod_inv(x, m):
    """Compute the modular multiplicative inverse of x under modulo m."""
    g, v, u = gcd(x, m), x, m
    if g != 1:
        raise ValueError('modular inverse does not exist')
    else:
        return u // g

class Memoize:
    """Memoize decorator for recursive functions."""
    def __init__(self, func):
        self.func = func
        self.memo = {}

    def __call__(self, arg):
        try:
            return self.memo[arg]
        except KeyError:
            res = self.func(arg)
            self.memo[arg] = res
            return res

@Memoize
def fib(n, p):
    """Compute the nth Fibonacci number modulo p."""
    if n < 0:
        return 0
    elif n == 0 or n == 1:
        return 0, p
    else:
        prev, next_ = fib(n-1, p), fib(n-2, p)
        return prev + next_, p

# Example usage
print(fib(1, 5))       # Output: (1, 5)
print(fib(4, 5))       # Output: (3, 5)
print(fib(5, 7))       # Output: (2, 7)

