import functools


@functools.lru_cache(maxsize=None)
def twisted_fib(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return (twisted_fib(n - 1) + twisted_fib(n - 2)) % 1000000007


def test_twisted_fib():
    # Provided data points to verify correctness
    assert twisted_fib(0) == 0
    assert twisted_fib(1) == 1
    assert twisted_fib(2) == 3
    assert twisted_fib(3) == 5
    assert twisted_fib(4) == 8
    assert twisted_fib(5) == 13
    assert twisted_fib(6) == 21
    print("All test cases passed successfully.")

